register('build_project','Type-check and compile a source snapshot into one GIA artifact. No live map writes; compilation may take up to two minutes. The result has limits: nodeCount and editorCount (the size the editor will count: a graph variable read or write is 4, a loop over a list 20, a counting loop 15, the rest 1) against maxNodes 3000, and warnings when the editor would refuse the graph or is close to it.',{projectId},a=>service.buildProject(a));
register('preview_changes','Validate replacement against current destination and return exact target hash and before/after graph summary. Does not write the destination.',{projectId,buildId,destination},a=>service.previewChanges(a),true);
register('apply_build','Apply a previously built graph after hash comparison, preserving a backup. Default destination is the project copy. Reload editor map before saving live changes.',{projectId,buildId,destination,expectedSha256},a=>service.applyBuild(a));
register('write_graphs','Write the source of node graphs into a copy of a save, one graph or many in one call: each {graphId, code} is type-checked, compiled and written in place of that graph, and the save with all of them is returned. graphId is a graph that exists in the save (scene_add_graph returned it; inspect_map lists them), code its whole Genshin-TS source. Returns the mapPath of the save with all of them written, and for each graph the size the editor will count (limits) and any warnings. If one does not compile it stops there: failed names the graph and carries the compiler\'s errors, mapPath is the save with the graphs written before it, and the call can be repeated with the corrected graph and the ones after it on that mapPath. A level of ten graphs is one call instead of fifty. The graphs of one call are type-checked and compiled together, which takes about as long as one graph alone (thirty-seven graphs: a quarter of a minute; one by one they took four and a half): send all the graphs of a level, or all that changed, in one call. After a change to a few graphs, send only those, on the mapPath that has the others. A defineSignal that does not agree with the signal in the save (other types, another order or count; for client:NAME the player first) is refused with the declaration to use (SIGNAL_PARAMETERS_DIFFER): the values travel by their place and the compiler would take any.',{
  mapPath:z.string(),graphs:z.array(z.object({graphId,code:z.string().min(1).max(200000)}).strict()).min(1).max(60)
},async a=>{
  let mapPath=a.mapPath;const written=[],stamp=Date.now().toString(36);
  // A signal declared with other values than the save's signal carries compiles and reads the wrong pins: said first.
  for(const [i,graph] of a.graphs.entries()){let faults=[];try{faults=signalDeclarationFaults({mapPath,code:graph.code});}catch{}
    if(faults.length)return {mapPath,written,failed:{graphId:graph.graphId,position:i,code:'SIGNAL_PARAMETERS_DIFFER',message:faults[0].problem,details:{signals:faults}},
      next:'Graph '+graph.graphId+' was not written: its defineSignal does not agree with the signal in the save (details.signals gives the declaration to use). Correct its source and call write_graphs again.'};}
  // All of them through the type check and the compiler in one go, and into one copy of the save in one pass. When the
  // compiling together does not work out (one of them has an error), each is built by itself below, which stops at the
  // graph at fault and reports its errors.
  // MILIASTRA_WRITE_ONE_BY_ONE=1 keeps to the old way, a graph at a time: for comparing the two, or if the batch misbehaves.
  const together=process.env.MILIASTRA_WRITE_ONE_BY_ONE==='1'?null:await service.compileTogether(a.graphs);
  if(together){
    const all=service.writeTogether({projectId:'w'+stamp,mapPath,graphs:a.graphs,gias:together});
    return all.failed?{mapPath:all.mapPath,written:all.written,failed:all.failed,next:'Graph '+all.failed.graphId+' was not written. Correct its source and call write_graphs again on this mapPath with it and the graphs after it.'}
      :{mapPath:all.mapPath,written:all.written,next:'All written. Play it: playtest_start {mapPath: this mapPath, graphNames: the graphs whose prints you want}.'};
  }
  for(const [i,graph] of a.graphs.entries()){
    const id='w'+stamp+'-'+i;
    try{
      await service.createProject({projectId:id,mapPath,targetGraphId:graph.graphId});
      await service.updateLogic({projectId:id,code:graph.code});
      const build=await service.buildProject({projectId:id});
      const preview=await service.previewChanges({projectId:id,buildId:build.buildId,destination:'copy'});
      const applied=await service.applyBuild({projectId:id,buildId:build.buildId,destination:'copy',expectedSha256:preview.expectedSha256});
      mapPath=applied.target;written.push({graphId:graph.graphId,projectId:id,limits:build.limits,warnings:build.warnings});
    }catch(e){
      return {mapPath,written,failed:{graphId:graph.graphId,position:i,code:e.code??'ERROR',message:e.message,details:e.details},
        next:'Graph '+graph.graphId+' was not written. Correct its source and call write_graphs again on this mapPath with it and the graphs after it.'};
    }
  }
  return {mapPath,written,next:'All written. Play it: playtest_start {mapPath: this mapPath, graphNames: the graphs whose prints you want}.'};
});
